contract InvMutTest {
    C c;
    address initialOwner;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public test entry; take an amount to forward to c.go
    function run(uint256 amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount, "insufficient test balance");

        // record observable state before the call
        address ownerBefore = c.owner(); if (__ESBMC_reverted()) return;
        uint256 balanceBefore = address(c).balance;

        // make the call and capture whether it reverted
        bool reverted;
        c.go{value: amount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // read observable state after the call
        address ownerAfter = c.owner(); if (__ESBMC_reverted()) return;
        uint256 balanceAfter = address(c).balance;

        // General rule:
        // - The owner address must not change as a result of go()
        // - If the call succeeded then the contract's balance must be zero (it forwards received ETH out)
        // We allow balanceAfter > 0 only if the call reverted (then state may be unchanged)
        assert(ownerAfter == ownerBefore && (reverted || balanceAfter == 0));
    }

    // allow receiving ETH when C forwards to this contract
    receive() external payable {}
}

